# Key observation: All 3s are between certain 2s
# Let me check if 3s appear along paths between specific pairs

points_2 = [(3,8), (6,4), (6,12), (9,10), (11,7)]

# Check bounding box hypothesis for ALL pairs
all_3s = {
    (4,8), (5,8), (6,5), (6,6), (6,7), (6,8), (6,9), (6,10), (6,11),
    (7,7), (8,7), (9,7), (10,7),
    (7,10), (8,10)
}

def manhattan(p1, p2):
    return abs(p1[0]-p2[0]) + abs(p1[1]-p2[1])

def is_on_path(cell, p1, p2):
    # Check if cell is on axis-aligned line segment between p1 and p2
    if cell[0] == p1[0] == p2[0]:  # Same row
        return min(p1[1], p2[1]) <= cell[1] <= max(p1[1], p2[1])
    if cell[1] == p1[1] == p2[1]:  # Same col  
        return min(p1[0], p2[0]) <= cell[0] <= max(p1[0], p2[0])
    return False

# Check if ALL 3s are on paths between pairs of 2s
for cell in all_3s:
    found = False
    for i in range(len(points_2)):
        for j in range(i+1, len(points_2)):
            if is_on_path(cell, points_2[i], points_2[j]):
                found = True
                break
        if found:
            break
    if not found:
        print(f"3 at {cell} is NOT on any path between pairs of 2s!")

print(f"Total 3s: {len(all_3s)}")

# Let me try grouping 2s based on some heuristic
# Like: form a polygon/triangle and fill something

points_2 = [(3,8), (6,4), (6,12), (9,10), (11,7)]

# Check if some 2s form triangles/trapezoids that get filled
# Let me try: triangles with the 3s being points on edges

import itertools

def distance_sq(p1, p2):
    return (p1[0]-p2[0])**2 + (p1[1]-p2[1])**2

def point_on_segment(p, a, b):
    # Check if p is on line segment ab
    # For axis-aligned, check if one coord matches and other is between
    if p[0] == a[0] == b[0]:
        return min(a[1], b[1]) <= p[1] <= max(a[1], b[1])
    if p[1] == a[1] == b[1]:
        return min(a[0], b[0]) <= p[0] <= max(a[0], b[0])
    return False

# For each triplet of 2s, check what axis-aligned "triangle" they form
# and if 3s fill certain regions
for comb in itertools.combinations(points_2, 3):
    p1, p2, p3 = comb
    # Maybe there's a bounding box pattern
    rows = min(r for r,c in comb)
    cols = min(c for r,c in comb)
    rows_max = max(r for r,c in comb)
    cols_max = max(c for r,c in comb)

    # Count 3s in the bounding box
    count = 0
    bbox_3s = []
    for r in range(rows, rows_max):
        for c in range(cols, cols_max):
            if (r,c) in all_3s:
                count += 1
                bbox_3s.append((r,c))

    if count > 0:
        print(f"Triplet {comb}: bbox = ({rows},{cols} to {rows_max},{cols_max}), 3s count={count}")

# Try a different approach: let's see what shapes the 3s themselves form
print("\nAnalyzing connected 3-components...")

# BFS to find connected components of 3s
from collections import deque

connected = {}
for cell in all_3s:
    visited = set()
    queue = deque([cell])
    component = []

    while queue:
        curr = queue.popleft()
        if curr in visited:
            continue
        visited.add(curr)
        component.append(curr)

        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nb = (curr[0]+dr, curr[1]+dc)
            if nb in all_3s and nb not in visited:
                queue.append(nb)

    connected[tuple(component)] = component
    print(f"Component with {len(component)} 3s: {component}")

# Try to see if 2s are connected via 3s
print("\nConnecting 2s via 3s...")
# A 3s connects two 2s if there are 3s forming a path
for cell in all_3s:
    # Find adjacent 2s
    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
        neighbor = (cell[0]+dr, cell[1]+dc)
        if neighbor in points_2:
            print(f"3 at {cell} touches 2 at {neighbor}")
